--
-- Table structure for table `document_line_items`
--

DROP TABLE IF EXISTS `document_line_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `document_line_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint unsigned NOT NULL,
  `documentable_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `documentable_id` bigint unsigned NOT NULL,
  `offering_id` bigint unsigned DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `unit_price` int NOT NULL DEFAULT '0',
  `subtotal` int GENERATED ALWAYS AS ((`quantity` * `unit_price`)) STORED,
  `total` int GENERATED ALWAYS AS ((((`quantity` * `unit_price`) + `tax_total`) - `discount_total`)) STORED,
  `tax_total` int NOT NULL DEFAULT '0',
  `discount_total` int NOT NULL DEFAULT '0',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `document_line_items_company_id_foreign` (`company_id`),
  KEY `document_line_items_documentable_type_documentable_id_index` (`documentable_type`,`documentable_id`),
  KEY `document_line_items_offering_id_foreign` (`offering_id`),
  KEY `document_line_items_created_by_foreign` (`created_by`),
  KEY `document_line_items_updated_by_foreign` (`updated_by`),
  CONSTRAINT `document_line_items_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `document_line_items_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `document_line_items_offering_id_foreign` FOREIGN KEY (`offering_id`) REFERENCES `offerings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `document_line_items_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1036 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

